import { API_BASE_URL } from '../config/api';

export interface Video {
  id: string;
  title: string;
  channel: string;
  views: number;
  durationSeconds: number;
  thumbnailUrl: string;
  description: string;
}

export async function fetchVideo(id: string): Promise<Video> {
  const response = await fetch(`${API_BASE_URL}/videos/${id}`);
  if (!response.ok) throw new Error(`Video failed with status ${response.status}`);
  return (await response.json()) as Video;
}

export async function fetchRelated(id: string, page: number): Promise<Video[]> {
  const response = await fetch(`${API_BASE_URL}/videos/${id}/related?page=${page}`);
  if (!response.ok) throw new Error(`Related failed with status ${response.status}`);
  return (await response.json()) as Video[];
}

import { useCallback, useEffect, useState } from 'react';
import { View, Text, TouchableOpacity, FlatList, Image, StyleSheet, SafeAreaView, ActivityIndicator } from 'react-native';
import { fetchVideo, fetchRelated, type Video } from '../services/videos';

const colors = {
  accent: '#f05039',
  bg: '#0f120e',
  danger: '#ff6b5e',
  muted: '#8a8f8a',
  border: '#242a24',
  text: '#f5f5f0',
  textMuted: '#a8ada6',
  textSoft: '#d8dbd4',
  borderAlt: '#2a2f2a',
}

const VIDEO_ID = 'video-1';

const formatViews = (n: number): string => (n >= 1_000_000 ? `${(n / 1_000_000).toFixed(1)}M` : n >= 1000 ? `${(n / 1000).toFixed(1)}K` : String(n));

export function VideoDetailScreen(): JSX.Element {
  const [video, setVideo] = useState<Video | null>(null);
  const [related, setRelated] = useState<Video[]>([]);
  const [page, setPage] = useState(1);
  const [loading, setLoading] = useState(true);
  const [relatedLoading, setRelatedLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [hasMore, setHasMore] = useState(true);

    const load = useCallback(async () => {

    try {
      const data = await fetchVideo(VIDEO_ID);
      setVideo(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load the video.');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    void load();
  }, [load]);

  const loadMore = useCallback(async () => {
    if (relatedLoading || !hasMore) return;
    setRelatedLoading(true);
    try {
      const next = await fetchRelated(VIDEO_ID, page);
      setRelated(prev => [...prev, ...next]);
      setPage(p => p + 1);
      setHasMore(next.length > 0);
    } catch {
      setHasMore(false);
    } finally {
      setRelatedLoading(false);
    }
  }, [page, relatedLoading, hasMore]);

  const renderRelated = useCallback(({ item }: { item: Video }) => (
    <View style={styles.relatedRow}>
      <Image source={{ uri: item.thumbnailUrl }} style={styles.thumb} accessibilityLabel={item.title} />
      <View style={styles.relatedInfo}>
        <Text style={styles.relatedTitle} numberOfLines={2}>{item.title}</Text>
        <Text style={styles.relatedMeta}>{item.channel} · {formatViews(item.views)} views</Text>
      </View>
    </View>
  ), []);

  if (loading) return <SafeAreaView style={styles.safe}><ActivityIndicator color="{colors.accent}" style={styles.center} /></SafeAreaView>;
  if (error && !video) return <SafeAreaView style={styles.safe}><Text style={styles.error}>{error}</Text></SafeAreaView>;
  if (!video) return <SafeAreaView style={styles.safe}><Text style={styles.empty}>Video unavailable.</Text></SafeAreaView>;

  const header = (
    <View>
      <TouchableOpacity style={styles.thumbWrap} accessibilityRole="button" accessibilityLabel="Play video" activeOpacity={0.8}>
        <Image source={{ uri: video.thumbnailUrl }} style={styles.thumbBig} />
        <View style={styles.playOverlay}><Text style={styles.playIcon}>▶</Text></View>
      </TouchableOpacity>
      <View style={styles.info}>
        <Text style={styles.title}>{video.title}</Text>
        <Text style={styles.meta}>{video.channel} · {formatViews(video.views)} views</Text>
        <Text style={styles.description}>{video.description}</Text>
      </View>
      <Text style={styles.relatedHeading}>Related</Text>
    </View>
  );

  return (
    <SafeAreaView style={styles.safe}>
      <FlatList
        data={related}
        renderItem={renderRelated}
        keyExtractor={v => v.id}
        ListHeaderComponent={header}
        ListFooterComponent={relatedLoading ? <ActivityIndicator color="{colors.accent}" /> : null}
        onEndReached={loadMore}
        onEndReachedThreshold={0.4}
      />
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  safe: { flex: 1, backgroundColor: colors.bg },
  center: { marginTop: 40 },
  error: { color: colors.danger, textAlign: 'center', marginTop: 24 },
  empty: { color: colors.muted, textAlign: 'center', marginTop: 24 },
  thumbWrap: { width: '100%', aspectRatio: 16 / 9, backgroundColor: colors.border },
  thumbBig: { width: '100%', height: '100%' },
  playOverlay: { ...StyleSheet.absoluteFillObject, alignItems: 'center', justifyContent: 'center', backgroundColor: 'rgba(0,0,0,0.35)' },
  playIcon: { color: colors.text, fontSize: 44 },
  info: { padding: 16 },
  title: { color: colors.text, fontSize: 18, fontWeight: '700' },
  meta: { color: colors.muted, fontSize: 12, marginTop: 6 },
  description: { color: colors.textMuted, marginTop: 12, lineHeight: 20 },
  relatedHeading: { color: colors.textSoft, fontWeight: '700', paddingHorizontal: 16, paddingBottom: 8 },
  relatedRow: { flexDirection: 'row', gap: 12, paddingHorizontal: 16, paddingVertical: 8 },
  thumb: { width: 128, height: 72, borderRadius: 6, backgroundColor: colors.borderAlt },
  relatedInfo: { flex: 1 },
  relatedTitle: { color: colors.text },
  relatedMeta: { color: colors.muted, fontSize: 11, marginTop: 4 },
});
